#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ifstream plik("slowa.txt");
    string s;
    int samogloski = 0, spolgloski = 0;
    while (plik >> s) {
        char c = s[0];
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u')
            samogloski++;
        else
            spolgloski++;
    }
    cout << "Slowa zaczynajace sie na samogloske: " << samogloski << endl;
    cout << "Slowa zaczynajace sie na spolgoske: " << spolgloski << endl;
    return 0;
}
```

Weryfikacja:
- Samogloska: algorytm(a), ekran(e), informatyka(i), okno(o), urzadzenie(u), egzamin(e), obliczenia(o), arkusz(a), element(e) = 9
- Spolgoska: baza(b), dane(d), system(s) = 3
